create or replace function public.bg_slug(_input text)
returns text language sql immutable as $$
  select trim(both '-' from regexp_replace(
    translate(
      replace(replace(replace(replace(replace(replace(replace(replace(lower(_input),
        'ж','zh'),'ц','ts'),'ч','ch'),'ш','sh'),'щ','sht'),'ю','yu'),'я','ya'),'кв.','kv'),
      'абвгдезийклмнопрстуфхъь','abvgdezijklmnoprstufhay'),
    '[^a-z0-9]+', '-', 'g'))
$$;

