insert into public.neighborhoods (municipality_id, name, slug, sort_order)
select m.id, n.name, public.bg_slug(n.name), n.ord - 1
from data d
join public.municipalities m on m.slug = d.mslug
cross join lateral unnest(d.names) with ordinality as n(name, ord)
on conflict (municipality_id, name) do nothing;

update public.municipalities m
set has_neighborhoods = true
where exists (select 1 from public.neighborhoods n where n.municipality_id = m.id)
  and m.has_neighborhoods = false;